  "UpdateSpritePaletteWithWeather": {
    returnType: "void",
    params: "u8 spritePaletteIndex",
    callsTo: ["ApplyColorMap","BlendPalette","CpuFastCopy","MarkFogSpritePalToLighten","PLTT_ID","RGB"],
    lineCount: 31,
    bodyC: "u16 paletteIndex = 16 + spritePaletteIndex;\n    u16 i;\n\n    switch (gWeatherPtr->palProcessingState)\n    {\n    case WEATHER_PAL_STATE_SCREEN_FADING_IN:\n        if (gWeatherPtr->fadeInFirstFrame)\n        {\n            if (gWeatherPtr->currWeather == WEATHER_FOG_HORIZONTAL)\n                MarkFogSpritePalToLighten(paletteIndex);\n            paletteIndex = PLTT_ID(paletteIndex);\n            for (i = 0; i < 16; i++)\n                gPlttBufferFaded[paletteIndex + i] = gWeatherPtr->fadeDestColor;\n        }\n        break;\n    case WEATHER_PAL_STATE_SCREEN_FADING_OUT:\n        paletteIndex = PLTT_ID(paletteIndex);\n        CpuFastCopy(&gPlttBufferFaded[paletteIndex], &gPlttBufferUnfaded[paletteIndex], PLTT_SIZE_4BPP);\n        BlendPalette(paletteIndex, 16, gPaletteFade.y, gPaletteFade.blendColor);\n        break;\n     \n     \n    default:\n        if (gWeatherPtr->currWeather != WEATHER_FOG_HORIZONTAL)\n        {\n            ApplyColorMap(paletteIndex, 1, gWeatherPtr->colorMapIndex);\n        }\n        else\n        {\n            paletteIndex = PLTT_ID(paletteIndex);\n            BlendPalette(paletteIndex, 16, 12, RGB(28, 31, 28));\n        }\n        break;\n    }",
  },
